#include <gtk/gtk.h>
#include <webkit2/webkit2.h>
#include <algorithm>
#include <cctype>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <string>
namespace fs=std::filesystem;
static constexpr const char* HOME_URL="https://www.google.com";
static constexpr const char* APP_VERSION="0.3.0";
struct Browser{GtkWidget*window{};GtkWidget*address{};GtkWidget*back{};GtkWidget*forward{};GtkWidget*reload{};GtkWidget*loading{};WebKitWebView*view{};WebKitWebContext*context{};fs::path profile;fs::path downloads;};
static Browser app;
static fs::path data_dir(){const char*base=g_get_user_data_dir();return fs::path(base?base:".")/"SwiftLife";}
static std::string trim(std::string v){v.erase(v.begin(),std::find_if(v.begin(),v.end(),[](unsigned char c){return !std::isspace(c);}));v.erase(std::find_if(v.rbegin(),v.rend(),[](unsigned char c){return !std::isspace(c);}).base(),v.end());return v;}
static std::string navigate_input(const std::string&raw){const std::string v=trim(raw);if(v.empty())return HOME_URL;if(v=="about:blank")return v;if(v.rfind("https://",0)==0||v.rfind("http://",0)==0)return v;if(v.find(' ')!=std::string::npos||v.find('.')==std::string::npos){gchar*e=g_uri_escape_string(v.c_str(),nullptr,true);std::string r="https://www.google.com/search?q="+std::string(e?e:"");g_free(e);return r;}return "https://"+v;}
static void save_session(const char*uri){if(!uri||g_str_has_prefix(uri,"about:"))return;std::error_code ec;fs::create_directories(app.profile,ec);std::ofstream o(app.profile/"last-session.url",std::ios::trunc);if(o)o<<uri<<'\n';}
static std::string load_session(){std::ifstream i(app.profile/"last-session.url");std::string u;std::getline(i,u);u=trim(u);return(u.rfind("https://",0)==0||u.rfind("http://",0)==0)?u:HOME_URL;}
static void update_navigation(Browser*b){if(!b->view)return;gtk_widget_set_sensitive(b->back,webkit_web_view_can_go_back(b->view));gtk_widget_set_sensitive(b->forward,webkit_web_view_can_go_forward(b->view));}
static void navigate(Browser*b,const std::string&in){if(!b->view)return;auto u=navigate_input(in);webkit_web_view_load_uri(b->view,u.c_str());}
static void on_address_activate(GtkEntry*e,gpointer d){auto*b=(Browser*)d;navigate(b,gtk_entry_get_text(e));gtk_widget_grab_focus(GTK_WIDGET(b->view));}
static void on_back(GtkButton*,gpointer d){webkit_web_view_go_back(((Browser*)d)->view);}static void on_forward(GtkButton*,gpointer d){webkit_web_view_go_forward(((Browser*)d)->view);}static void on_reload(GtkButton*,gpointer d){webkit_web_view_reload(((Browser*)d)->view);}static void on_home(GtkButton*,gpointer d){navigate((Browser*)d,HOME_URL);}
static void on_load_changed(WebKitWebView*v,WebKitLoadEvent e,gpointer d){auto*b=(Browser*)d;if(e==WEBKIT_LOAD_STARTED)gtk_widget_show(b->loading);if(e==WEBKIT_LOAD_FINISHED||e==WEBKIT_LOAD_FAILED)gtk_widget_hide(b->loading);if(e==WEBKIT_LOAD_COMMITTED||e==WEBKIT_LOAD_FINISHED){const char*u=webkit_web_view_get_uri(v);if(u){gtk_entry_set_text(GTK_ENTRY(b->address),u);save_session(u);}update_navigation(b);}}
static void on_title_changed(GObject*o,GParamSpec*,gpointer d){auto*b=(Browser*)d;const char*t=webkit_web_view_get_title(WEBKIT_WEB_VIEW(o));std::string s=t&&*t?t:"SwiftLife";gtk_window_set_title(GTK_WINDOW(b->window),(s+" — SwiftLife").c_str());}
static gboolean on_decide_policy(WebKitWebView*,WebKitPolicyDecision*dec,WebKitPolicyDecisionType type,gpointer){if(type!=WEBKIT_POLICY_DECISION_TYPE_NAVIGATION_ACTION)return FALSE;auto*a=webkit_navigation_policy_decision_get_navigation_action(WEBKIT_NAVIGATION_POLICY_DECISION(dec));auto*r=webkit_navigation_action_get_request(a);const char*u=webkit_uri_request_get_uri(r);if(!u)return TRUE;if(g_str_has_prefix(u,"http://")||g_str_has_prefix(u,"https://")||g_str_has_prefix(u,"about:"))return FALSE;webkit_policy_decision_ignore(dec);return TRUE;}
static WebKitWebView*on_create(WebKitWebView*,WebKitNavigationAction*,gpointer d){return((Browser*)d)->view;}
static std::string safe_filename(const char*uri){std::string f="download";if(uri){gchar*p=g_uri_unescape_string(uri,nullptr);const char*s=p?p:uri;const char*slash=strrchr(s,'/');if(slash&&*(slash+1))f=slash+1;g_free(p);}while(!f.empty()&&(f.back()==' '||f.back()=='.'))f.pop_back();for(char&c:f)if(std::iscntrl((unsigned char)c)||c=='/'||c=='\\'||c==':'||c=='"'||c=='<'||c=='>'||c=='|')c='_';return f.empty()?"download":f;}
static void on_download_started(WebKitWebContext*,WebKitDownload*dl,gpointer d){auto*b=(Browser*)d;std::error_code ec;fs::create_directories(b->downloads,ec);auto*r=webkit_download_get_request(dl);const char*u=r?webkit_uri_request_get_uri(r):nullptr;std::string f=safe_filename(u);fs::path t=b->downloads/f;for(unsigned n=1;fs::exists(t,ec)&&n<10000;++n)t=b->downloads/(f+" ("+std::to_string(n)+")");gchar*dest=g_filename_to_uri(t.c_str(),nullptr,nullptr);if(dest){webkit_download_set_destination(dl,dest);g_free(dest);}}
static gboolean on_context_menu(WebKitWebView*,WebKitContextMenu*menu,GdkEvent*,WebKitHitTestResult*hit,gpointer){if(!menu||!hit)return FALSE;if(webkit_hit_test_result_context_is_link(hit))webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_DOWNLOAD_LINK_TO_DISK,"SwiftLife ile bağlantıyı indir"));if(webkit_hit_test_result_context_is_image(hit))webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_DOWNLOAD_IMAGE_TO_DISK,"Görseli SwiftLife ile indir"));return FALSE;}
static GtkWidget*icon_button(const char*icon,const char*tip,GCallback cb,Browser*b){GtkWidget*w=gtk_button_new();gtk_widget_set_name(w,"toolbar-button");gtk_widget_set_tooltip_text(w,tip);gtk_button_set_image(GTK_BUTTON(w),gtk_image_new_from_icon_name(icon,GTK_ICON_SIZE_BUTTON));gtk_button_set_always_show_image(GTK_BUTTON(w),TRUE);g_signal_connect(w,"clicked",cb,b);return w;}
static void apply_css(){const char*css=R"CSS(*{-GtkWidget-focus-line-width:0;}window{background:#0b0f15;}#toolbar{background:#111720;border-bottom:1px solid #293241;padding:8px 10px;}#brand{color:#f6f8fc;font-weight:800;font-size:15px;padding:0 10px 0 2px;}#toolbar-button{background:#171e29;color:#d8dee8;border:1px solid #303b4b;border-radius:10px;padding:5px 7px;min-width:36px;min-height:34px;}#toolbar-button:hover{background:#242d3a;color:#fff;border-color:#46546a;}#toolbar-button:disabled{opacity:.42;}#address{background:#0d131b;color:#eef2f7;border:1px solid #344052;border-radius:13px;padding:8px 14px;min-height:34px;}#address:focus{border-color:#7866e8;}#loading{color:#8f7cff;padding:0 7px;})CSS";GtkCssProvider*p=gtk_css_provider_new();gtk_css_provider_load_from_data(p,css,-1,nullptr);gtk_style_context_add_provider_for_screen(gdk_screen_get_default(),GTK_STYLE_PROVIDER(p),GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);g_object_unref(p);}
static void activate(GtkApplication*application,gpointer){std::error_code ec;app.profile=data_dir()/"profile";const char*dd=g_get_user_special_dir(G_USER_DIRECTORY_DOWNLOAD);app.downloads=fs::path(dd?dd:data_dir().c_str())/"SwiftLife";fs::create_directories(app.profile,ec);fs::create_directories(app.downloads,ec);app.window=gtk_application_window_new(application);gtk_window_set_default_size(GTK_WINDOW(app.window),1440,900);gtk_window_set_title(GTK_WINDOW(app.window),"SwiftLife");gtk_window_set_position(GTK_WINDOW(app.window),GTK_WIN_POS_CENTER);gtk_window_set_icon_name(GTK_WINDOW(app.window),"swiftlife");apply_css();GtkWidget*root=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_container_add(GTK_CONTAINER(app.window),root);GtkWidget*bar=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,6);gtk_widget_set_name(bar,"toolbar");gtk_box_pack_start(GTK_BOX(root),bar,FALSE,FALSE,0);GtkWidget*brand=gtk_label_new("SwiftLife");gtk_widget_set_name(brand,"brand");gtk_box_pack_start(GTK_BOX(bar),brand,FALSE,FALSE,0);app.back=icon_button("go-previous-symbolic","Geri",G_CALLBACK(on_back),&app);app.forward=icon_button("go-next-symbolic","İleri",G_CALLBACK(on_forward),&app);app.reload=icon_button("view-refresh-symbolic","Yenile",G_CALLBACK(on_reload),&app);GtkWidget*home=icon_button("go-home-symbolic","Ana sayfa",G_CALLBACK(on_home),&app);gtk_box_pack_start(GTK_BOX(bar),app.back,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),app.forward,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),app.reload,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),home,FALSE,FALSE,0);app.address=gtk_entry_new();gtk_widget_set_name(app.address,"address");gtk_entry_set_placeholder_text(GTK_ENTRY(app.address),"Adres yazın veya hızlıca web'de arayın…");gtk_entry_set_icon_from_icon_name(GTK_ENTRY(app.address),GTK_ENTRY_ICON_PRIMARY,"system-search-symbolic");gtk_box_pack_start(GTK_BOX(bar),app.address,TRUE,TRUE,5);g_signal_connect(app.address,"activate",G_CALLBACK(on_address_activate),&app);app.loading=gtk_label_new("●");gtk_widget_set_name(app.loading,"loading");gtk_widget_hide(app.loading);gtk_box_pack_end(GTK_BOX(bar),app.loading,FALSE,FALSE,0);auto*manager=webkit_website_data_manager_new("base-data-directory",app.profile.c_str(),"base-cache-directory",(app.profile/"cache").c_str(),nullptr);app.context=webkit_web_context_new_with_website_data_manager(manager);g_object_unref(manager);webkit_web_context_set_cache_model(app.context,WEBKIT_CACHE_MODEL_WEB_BROWSER);g_signal_connect(app.context,"download-started",G_CALLBACK(on_download_started),&app);app.view=WEBKIT_WEB_VIEW(webkit_web_view_new_with_context(app.context));gtk_widget_set_hexpand(GTK_WIDGET(app.view),TRUE);gtk_widget_set_vexpand(GTK_WIDGET(app.view),TRUE);gtk_box_pack_end(GTK_BOX(root),GTK_WIDGET(app.view),TRUE,TRUE,0);g_signal_connect(app.view,"load-changed",G_CALLBACK(on_load_changed),&app);g_signal_connect(app.view,"notify::title",G_CALLBACK(on_title_changed),&app);g_signal_connect(app.view,"decide-policy",G_CALLBACK(on_decide_policy),&app);g_signal_connect(app.view,"create",G_CALLBACK(on_create),&app);g_signal_connect(app.view,"context-menu",G_CALLBACK(on_context_menu),&app);auto*settings=webkit_web_view_get_settings(app.view);webkit_settings_set_enable_developer_extras(settings,TRUE);webkit_settings_set_enable_smooth_scrolling(settings,TRUE);webkit_settings_set_enable_media_stream(settings,TRUE);webkit_settings_set_enable_dns_prefetching(settings,TRUE);gtk_widget_show_all(app.window);gtk_widget_hide(app.loading);navigate(&app,load_session());gtk_widget_grab_focus(GTK_WIDGET(app.view));}
int main(int argc,char**argv){for(int i=1;i<argc;++i)if(std::strcmp(argv[i],"--version")==0){g_print("SwiftLife %s (C++17 + GTK3 + WebKitGTK 4.1)\n",APP_VERSION);return 0;}GtkApplication*application=gtk_application_new("com.swiftlife.Browser",G_APPLICATION_DEFAULT_FLAGS);g_signal_connect(application,"activate",G_CALLBACK(activate),nullptr);int status=g_application_run(G_APPLICATION(application),argc,argv);g_object_unref(application);return status;}
